/**
 * 谱师列表取数：直接拿 infos.json 在浏览器里现算（不再读预生成的 charters.json）。
 *
 * 分组逻辑在 charterGroup.js，这里只负责取数、补曲绘与难度色。
 * infos.json 是站内共享数据，走 jsonCache 的请求缓存，不会因为多一个页面而重复下载。
 */
import { loadJson } from './jsonCache.js'
import { decorateGroupedSongMap } from './common.js'
import { CHARTER_DIFFICULTIES, groupByCharter } from './charterGroup.js'

export async function getCharterGroups() {
  try {
    const songData = await loadJson('/files/infos/infos.json')
    return decorateGroupedSongMap(groupByCharter(songData), CHARTER_DIFFICULTIES)
  } catch (error) {
    console.error('获取谱师数据失败：', error)
    return {}
  }
}
