/**
 * 各数据模块共用的常量与工具。
 * 这些内容原本在 7 个 *Get.vue 里各抄了一份。
 */

/** 数据与静态资源的前缀（部署在子路径时改这里即可） */
export const NET = ''

/** 难度配色 */
export const DIF_COLORS = {
  EZ: '#0D9A28',
  HD: '#0175B8',
  IN: '#CF1313',
  AT: '#383838',
  SP: '#383838',
  LY: '#383838',
  Legacy: '#383838'
}

export const DEFAULT_DIF_COLOR = '#383838'

export function difColor(dif) {
  return DIF_COLORS[dif] || DEFAULT_DIF_COLOR
}

/** RKS 精确值：固定四位小数（17.3 → 17.3000，16 → 16.0000） */
export function formatRks(value) {
  return Number(value).toFixed(4)
}

/** 低分辨率曲绘；variant 为负数是旧版曲绘（-1、-2…，见 python/getLvmdf.py） */
export function illLowPath(songId, variant = 0) {
  // 旧版曲绘把曲 ID 末尾的谱面序号换成本次要用的那一版：X.0.png → X.-1.png
  if (variant) songId = songId.replace(/\.0$/, '') + `.${variant}`
  return `${NET}/assets/illLow/${songId}.png`
}

/** 高分辨率曲绘 */
export function illPath(songId) {
  return `${NET}/assets/ill/${songId}.png`
}

/**
 * 个别曲目每档难度用的曲绘不一样：这首的 EZ/HD/IN/AT 分别用 .0/.1/.2/.3 四版曲绘。
 * 键名 → 难度 → 曲绘序号（序号规则同 illLowPath：把曲 ID 末尾的 .0 换成本次序号）。
 */
const DIFF_COVERS = {
  'WhatdoyouwantmorethanaHappyending.Apo11oHALOprogramft安月名莉子大瀬良あい.0': {
    EZ: 0,
    HD: 1,
    IN: 2,
    AT: 3
  }
}

/** 按难度取低清曲绘：这首歌这一档有专属曲绘就用它，否则用传入的历史版本 */
export function chartCover(songId, diff, variant = 0) {
  const perDiff = DIFF_COVERS[songId]
  return illLowPath(songId, perDiff && diff in perDiff ? perDiff[diff] : variant)
}

/** 给一首歌补上封面地址与各难度配色（就地修改） */
export function decorateSong(song, songId, diffs = ['EZ', 'HD', 'IN', 'AT']) {
  if (!song || typeof song !== 'object') return song
  // 定数变更的历史卡片带着 ill（第几张旧曲绘），按它取对应年代的曲绘
  song.cover = illLowPath(songId, song.ill || 0)
  for (const dif of diffs) {
    if (song[dif]) song[dif].color = difColor(dif)
  }
  return song
}

/** 截至 ymd（YYYYMMDD）这首歌用的是第几张旧曲绘：-1、-2…，0 表示现用曲绘 */
export function illVariantAt(illChange, songId, ymd) {
  const dates = illChange && illChange[songId]
  if (!dates || !dates.length || !ymd) return 0
  const passed = dates.filter((date) => date <= ymd).length
  return passed < dates.length ? -(passed + 1) : 0
}

/** 给「歌曲键名 → 歌曲」结构的整份数据补封面与配色 */
export function decorateSongMap(data, diffs = ['EZ', 'HD', 'IN', 'AT'], illChange = null, ymd = 0) {
  if (!data || typeof data !== 'object') return data
  for (const songId of Object.keys(data)) {
    const song = data[songId]
    // 按年份翻老页面时，曲绘换成那一年那张
    const variant = illChange ? illVariantAt(illChange, songId, ymd) : 0
    if (variant) song.ill = variant
    decorateSong(song, songId, diffs)
  }
  return data
}

/** 给「分组 → 歌曲键名 → 歌曲」结构的整份数据补封面与配色 */
export function decorateGroupedSongMap(data, diffs = ['EZ', 'HD', 'IN', 'AT']) {
  if (!data || typeof data !== 'object') return data
  for (const groupKey of Object.keys(data)) {
    decorateSongMap(data[groupKey], diffs)
  }
  return data
}
